const input = $json;
const q = input.qualification || {};
const score = Math.max(0, Math.min(100, Number(q.score) || 0));
const priority = score >= 80 ? 'High' : score >= 55 ? 'Medium' : 'Low';
return [{ json: { leadId: input.leadId, category: q.category || 'General', score, priority, summary: q.summary || 'No summary returned.', reason: q.reason || 'No reason returned.', recommendedAction: q.recommendedAction || 'Review manually.', source: input.source || 'fallback-rules' } }];
